from pydantic import BaseModel, Field, field_validator, ValidationError

class Answer(BaseModel):
    text: str
    confidence: float = Field(ge=0, le=1)
    sources: list[str] = []

    @field_validator("text")
    @classmethod
    def not_empty(cls, v: str) -> str:
        if not v.strip():
            raise ValueError("empty answer")
        return v

