import random, time

def with_retry(fn, attempts=4, base=0.5):
    for i in range(attempts):
        try:
            return fn()
        except TimeoutError:
            if i == attempts - 1:
                raise
            time.sleep(base * 2 ** i + random.random() * 0.1)   # exponential backoff + jitter

